import{_ as s,H as t,f as n,i as e}from"./chunks/framework.nyB-Xt5O.js";const u=JSON.parse('{"title":"Tableau 实战","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge-map/km-6-bi-visualization/05-tableau.md","filePath":"knowledge-map/km-6-bi-visualization/05-tableau.md","lastUpdated":1779798726000}'),l={name:"knowledge-map/km-6-bi-visualization/05-tableau.md"};function i(o,a,p,d,r,c){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="tableau-实战" tabindex="-1">Tableau 实战 <a class="header-anchor" href="#tableau-实战" aria-label="Permalink to &quot;Tableau 实战&quot;">​</a></h1><blockquote><p>Tableau 是当前市场占有率最高的 BI 工具之一，以其<strong>拖拽式交互</strong>和<strong>强大的可视化能力</strong>著称。本节覆盖从数据连接到高级 LOD 表达式的核心实战技能。</p></blockquote><h2 id="数据连接-data-connection" tabindex="-1">数据连接（Data Connection） <a class="header-anchor" href="#数据连接-data-connection" aria-label="Permalink to &quot;数据连接（Data Connection）&quot;">​</a></h2><h3 id="连接类型" tabindex="-1">连接类型 <a class="header-anchor" href="#连接类型" aria-label="Permalink to &quot;连接类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>连接方式</th><th>适用场景</th><th>性能特点</th></tr></thead><tbody><tr><td><strong>Live（实时连接）</strong></td><td>数据实时更新、小数据量</td><td>查询实时发送到源数据库</td></tr><tr><td><strong>Extract（数据提取）</strong></td><td>大数据量、需要加速</td><td>提取到 Tableau 自己的列式存储（.hyper），支持增量刷新</td></tr><tr><td><strong>Published Data Source</strong></td><td>团队共享数据源</td><td>发布到 Tableau Server，统一数据口径</td></tr></tbody></table><h3 id="数据源连接要点" tabindex="-1">数据源连接要点 <a class="header-anchor" href="#数据源连接要点" aria-label="Permalink to &quot;数据源连接要点&quot;">​</a></h3><ul><li><strong>双轴（Dual Axis）</strong> vs <strong>混合连接（Data Blending）</strong>：双轴在同一数据源级别操作，混和连接在不同粒度间连接（类似 LEFT JOIN）</li><li><strong>数据解释器（Data Interpreter）</strong>：自动识别和清理 Excel/PDF 中的杂项表头</li><li><strong>Union（纵向合并）与 Join（横向连接）</strong>：Union 用于多张结构相同的表，Join 用于关联表</li></ul><div class="tip custom-block"><p class="custom-block-title">连接策略</p><p>对于 <strong>亿级以上的数据</strong>，优先考虑 Extract + 增量刷新，而不是 Live 连接。Tableau Server 上可以设置提取刷新调度（建议在业务低峰期执行）。</p></div><h2 id="计算字段-calculated-fields" tabindex="-1">计算字段（Calculated Fields） <a class="header-anchor" href="#计算字段-calculated-fields" aria-label="Permalink to &quot;计算字段（Calculated Fields）&quot;">​</a></h2><h3 id="常用函数分类" tabindex="-1">常用函数分类 <a class="header-anchor" href="#常用函数分类" aria-label="Permalink to &quot;常用函数分类&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-- 逻辑函数</span></span>
<span class="line"><span>IF [Sales] &gt; 1000 THEN &quot;High&quot; ELSE &quot;Low&quot; END</span></span>
<span class="line"><span>CASE [Region] WHEN &quot;East&quot; THEN &quot;E&quot; ELSE &quot;O&quot; END</span></span>
<span class="line"><span>IIF([Profit] &gt; 0, &quot;Profitable&quot;, &quot;Loss&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 聚合函数</span></span>
<span class="line"><span>SUM([Sales])</span></span>
<span class="line"><span>AVG([Discount])</span></span>
<span class="line"><span>COUNTD([Customer ID])</span></span>
<span class="line"><span>MEDIAN([Price])</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 表计算函数 -- 见下一节</span></span>
<span class="line"><span>-- LOD 表达式 -- 见下下节</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 日期函数</span></span>
<span class="line"><span>DATETRUNC(&#39;month&#39;, [Order Date])</span></span>
<span class="line"><span>DATEDIFF(&#39;day&#39;, [Order Date], [Ship Date])</span></span>
<span class="line"><span>DATEADD(&#39;year&#39;, 1, [Order Date])</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 字符串函数</span></span>
<span class="line"><span>LEFT([Customer Name], 3)</span></span>
<span class="line"><span>CONTAINS([Product Name], &quot;iPhone&quot;)</span></span>
<span class="line"><span>REPLACE([Category], &quot;Tech&quot;, &quot;Technology&quot;)</span></span></code></pre></div><h3 id="字段类型" tabindex="-1">字段类型 <a class="header-anchor" href="#字段类型" aria-label="Permalink to &quot;字段类型&quot;">​</a></h3><p>Tableau 中的字段分为三类：</p><ol><li><strong>Dimensions（维度）</strong> — 离散的、分类的（蓝色药丸）</li><li><strong>Measures（度量）</strong> — 连续的、数值的（绿色药丸）</li><li><strong>Parameters（参数）</strong> — 用户可控制的值（详见参数节）</li></ol><h2 id="表计算-table-calculations" tabindex="-1">表计算（Table Calculations） <a class="header-anchor" href="#表计算-table-calculations" aria-label="Permalink to &quot;表计算（Table Calculations）&quot;">​</a></h2><p>表计算是对<strong>查询结果</strong>的二次计算，不是对底层数据的计算。这是 Tableau 最强大但也最容易让新手困惑的特性。</p><h3 id="核心概念-分区-partitioning-与寻址-addressing" tabindex="-1">核心概念：分区（Partitioning）与寻址（Addressing） <a class="header-anchor" href="#核心概念-分区-partitioning-与寻址-addressing" aria-label="Permalink to &quot;核心概念：分区（Partitioning）与寻址（Addressing）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>分区（Partition）-- 计算&quot;对谁分组&quot;，类似于 SQL 的 PARTITION BY</span></span>
<span class="line"><span>寻址（Addressing）-- 计算&quot;往哪个方向&quot;，决定排序方向</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例：RUNNING_SUM(SUM([Sales]))</span></span>
<span class="line"><span>  分区 = 空（整个表）</span></span>
<span class="line"><span>  寻址 = 按日期升序</span></span>
<span class="line"><span>  结果 = 累计销售额</span></span></code></pre></div><h3 id="常用表计算" tabindex="-1">常用表计算 <a class="header-anchor" href="#常用表计算" aria-label="Permalink to &quot;常用表计算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>RUNNING_SUM</code></td><td>累计求和</td><td>累计营收</td></tr><tr><td><code>WINDOW_SUM</code></td><td>窗口求和</td><td>过去 7 天移动和</td></tr><tr><td><code>TOTAL</code></td><td>分区总和</td><td>每个区域占总体的占比</td></tr><tr><td><code>PREVIOUS_VALUE</code></td><td>上一个值</td><td>环比计算</td></tr><tr><td><code>RANK</code></td><td>排名</td><td>销售排名</td></tr><tr><td><code>PERCENTILE</code></td><td>百分位</td><td>第 90 分位数</td></tr><tr><td><code>INDEX</code></td><td>位置索引</td><td>辅助排序</td></tr><tr><td><code>FIRST()</code> / <code>LAST()</code></td><td>到第一个/最后一个的距离</td><td>辅助计算</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>快速表计算（Quick Table Calculation）：右键度量 → 快速表计算</span></span>
<span class="line"><span>可以快速实现：运行总和、差异、百分比差异、总计百分比、排名、百分位、移动平均</span></span></code></pre></div><h2 id="lod-表达式-level-of-detail-expressions" tabindex="-1">LOD 表达式（Level of Detail Expressions） <a class="header-anchor" href="#lod-表达式-level-of-detail-expressions" aria-label="Permalink to &quot;LOD 表达式（Level of Detail Expressions）&quot;">​</a></h2><p>LOD 表达式允许你<strong>在不同于视图粒度的层级上进行计算</strong>，是 Tableau 最强大的高级功能。</p><h3 id="三种-lod-类型" tabindex="-1">三种 LOD 类型 <a class="header-anchor" href="#三种-lod-类型" aria-label="Permalink to &quot;三种 LOD 类型&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FIXED:   在指定维度级别计算，不受视图筛选影响</span></span>
<span class="line"><span>INCLUDE: 在视图维度基础上增加维度进行计算</span></span>
<span class="line"><span>EXCLUDE: 从视图维度中移除指定维度进行计算</span></span></code></pre></div><h3 id="实战案例" tabindex="-1">实战案例 <a class="header-anchor" href="#实战案例" aria-label="Permalink to &quot;实战案例&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-- 客户首单日期（FIXED）</span></span>
<span class="line"><span>{FIXED [Customer ID] : MIN([Order Date])}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 每个客户的总消费（FIXED）</span></span>
<span class="line"><span>{FIXED [Customer ID] : SUM([Sales])}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 每个产品类别中的销售排名（INCLUDE）</span></span>
<span class="line"><span>{INCLUDE [Category] : RANK(SUM([Sales]))}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 从视图维度中排除日期，获取总销售额（EXCLUDE）</span></span>
<span class="line"><span>{EXCLUDE [Order Date] : SUM([Sales])}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 客户级平均消费（FIXED + AVG 嵌套）</span></span>
<span class="line"><span>AVG({FIXED [Customer ID] : SUM([Sales])})</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">LOD 性能注意</p><p>LOD 表达式在数据源级别执行，复杂嵌套 LOD 会影响查询性能。建议在 Extract 模式下测试后再发布到 Server。</p></div><h2 id="参数-parameters" tabindex="-1">参数（Parameters） <a class="header-anchor" href="#参数-parameters" aria-label="Permalink to &quot;参数（Parameters）&quot;">​</a></h2><p>参数让用户可以通过控件（下拉框、滑块）动态改变计算或筛选条件。</p><h3 id="常用场景" tabindex="-1">常用场景 <a class="header-anchor" href="#常用场景" aria-label="Permalink to &quot;常用场景&quot;">​</a></h3><ul><li>动态 Top N：<code>RANK(SUM([Sales])) &lt;= [Top N Parameter]</code></li><li>动态参考线：显示用户输入的目标值</li><li>动态切换度量：用一个参数控制展示销售额/利润/数量</li><li>日期范围选择</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>参数创建示例：</span></span>
<span class="line"><span>  名称: [Top N]</span></span>
<span class="line"><span>  数据类型: Integer</span></span>
<span class="line"><span>  允许值: Range (1 to 50, step 1)</span></span>
<span class="line"><span>  显示格式: # 名</span></span>
<span class="line"><span></span></span>
<span class="line"><span>应用方式：</span></span>
<span class="line"><span>  创建计算字段 [Top N Filter]:</span></span>
<span class="line"><span>    RANK(SUM([Sales])) &lt;= [Top N]</span></span>
<span class="line"><span>  将此字段拖到筛选器，选择 True</span></span></code></pre></div><h2 id="集与动作-sets-actions" tabindex="-1">集与动作（Sets &amp; Actions） <a class="header-anchor" href="#集与动作-sets-actions" aria-label="Permalink to &quot;集与动作（Sets &amp; Actions）&quot;">​</a></h2><h3 id="集-sets" tabindex="-1">集（Sets） <a class="header-anchor" href="#集-sets" aria-label="Permalink to &quot;集（Sets）&quot;">​</a></h3><p>集合是数据的一个子集，基于条件或手动选择创建：</p><ul><li><strong>条件集</strong>：<code>Top 10 Customers by Sales</code> → <code>TOP_N(SUM([Sales]), 10)</code></li><li><strong>组合集</strong>：两个集合的并集/交集/差集</li></ul><h3 id="动作-actions" tabindex="-1">动作（Actions） <a class="header-anchor" href="#动作-actions" aria-label="Permalink to &quot;动作（Actions）&quot;">​</a></h3><p>Tableau 支持三种动作类型：</p><table tabindex="0"><thead><tr><th>动作类型</th><th>触发方式</th><th>作用</th></tr></thead><tbody><tr><td><strong>筛选动作（Filter Action）</strong></td><td>悬停/选择/双击</td><td>点击一个图表，筛选其他视图</td></tr><tr><td><strong>高亮动作（Highlight Action）</strong></td><td>悬停</td><td>悬停时高亮同类数据</td></tr><tr><td><strong>URL 动作（URL Action）</strong></td><td>点击</td><td>跳转到外部链接</td></tr><tr><td><strong>参数动作（Parameter Action）</strong></td><td>点击</td><td>用点击值更新参数</td></tr></tbody></table><p><strong>实践建议</strong>：在 Dashboard 层面配置交叉筛选时，使用&quot;选择&quot;而非&quot;悬停&quot;作为触发条件，避免误触干扰。</p><h2 id="dashboard-交互性" tabindex="-1">Dashboard 交互性 <a class="header-anchor" href="#dashboard-交互性" aria-label="Permalink to &quot;Dashboard 交互性&quot;">​</a></h2><ul><li><strong>浮动容器（Floating Containers）</strong>：实现覆盖、弹窗效果</li><li><strong>工具提示（Tooltip）</strong>：在 Tooltip 中嵌入视图（图表中的图表）</li><li><strong>导航按钮（Navigation Button）</strong>：实现多页面跳转</li><li><strong>突出显示表（Highlight Table）</strong>：在明细表上实现热力图效果</li><li><strong>自定义形状（Custom Shapes）</strong>：用图标替代默认圆形</li></ul><h2 id="性能优化要点" tabindex="-1">性能优化要点 <a class="header-anchor" href="#性能优化要点" aria-label="Permalink to &quot;性能优化要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>诊断方法</th><th>解决方案</th></tr></thead><tbody><tr><td>查询慢</td><td>帮助 → 设置和性能 → 启动性能记录</td><td>使用 Extract、减少 LOD 嵌套、优化数据源索引</td></tr><tr><td>Dashboard 加载慢</td><td>性能记录中查看各个视图的加载时间</td><td>减少 Dashboard 中的工作表数量、使用显示/隐藏容器</td></tr><tr><td>渲染慢</td><td>检查标记卡中的元素数量</td><td>减少数据点（聚合采样）、关闭不必要的标记叠加</td></tr><tr><td>交互卡顿</td><td>检查动作和计算复杂度</td><td>简化跨 Dashboard 筛选、减少实时计算</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>性能检查清单：</span></span>
<span class="line"><span>  ☐ 使用 Extract 而非 Live 连接（大数据量）</span></span>
<span class="line"><span>  ☐ 减少 Dashboard 上的工作表数量（≤ 6 个）</span></span>
<span class="line"><span>  ☐ 避免在 Dashboard 中使用 LOD 表达式的交叉计算</span></span>
<span class="line"><span>  ☐ 数据聚合在数据库层完成（不要在 Tableau 中做 ETL）</span></span>
<span class="line"><span>  ☐ 关闭不必要的数据源筛选器</span></span>
<span class="line"><span>  ☐ 使用&quot;保留隐藏工作表&quot;功能减少冗余计算</span></span></code></pre></div><h2 id="相关文章" tabindex="-1">相关文章 <a class="header-anchor" href="#相关文章" aria-label="Permalink to &quot;相关文章&quot;">​</a></h2><ul><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/06-powerbi">Power BI 实战</a> — 对比 Tableau 与 Power BI 的功能差异</li><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/07-open-source">开源方案</a> — Metabase 和 Superset 的开源替代方案</li></ul>`,48)])])}const b=s(l,[["render",i]]);export{u as __pageData,b as default};
